import { catalog } from "./catalog.ts";

type Catalog = typeof catalog;
export type MessageKey = keyof Catalog;
export type Value = string | number;

/** Every key of the catalog mapped to a translated string; `de.ts` must satisfy it. */
export type Translation = { readonly [K in MessageKey]: string };

type Same<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false;

type Placeholders<T extends string> = T extends `${string}{${infer Name}}${infer Rest}`
  ? Name | Placeholders<Rest>
  : never;

/** Keys whose `{placeholders}` differ from English; `never` when the translation is consistent. */
export type Mismatched<T extends Translation> = {
  [K in MessageKey]: Same<Placeholders<Catalog[K]>, Placeholders<T[K]>> extends true ? never : K;
}[MessageKey];

export type Params<K extends MessageKey> = Readonly<Record<Placeholders<Catalog[K]>, Value>>;
export type KeysWithoutParams = {
  [K in MessageKey]: [Placeholders<Catalog[K]>] extends [never] ? K : never;
}[MessageKey];
export type KeysWithParams = Exclude<MessageKey, KeysWithoutParams>;

type PluralBase<K extends string> = K extends `${infer Base}.other` ? Base : never;
export type PluralKey = PluralBase<MessageKey>;
export type PluralParams<B extends PluralKey> = Readonly<
  Record<Exclude<Placeholders<Catalog[`${B}.other`]>, "count">, Value>
>;

const LOCALE = "en";
let cachedPluralRules: Intl.PluralRules | undefined;
function getPluralRules(): Intl.PluralRules {
  if (!cachedPluralRules) {
    cachedPluralRules = new Intl.PluralRules(LOCALE);
  }
  return cachedPluralRules;
}

const isMessageKey = (key: string): key is MessageKey => Object.hasOwn(catalog, key);

export function fill(template: string, params: Readonly<Record<string, Value>>): string {
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(params[name] ?? ""));
}

/** Looks up a message; placeholders are checked against the template at compile time. */
export function message<K extends KeysWithoutParams>(key: K): string;
export function message<K extends KeysWithParams>(key: K, params: Params<K>): string;
export function message(key: MessageKey, params: Readonly<Record<string, Value>> = {}): string {
  return fill(catalog[key], params);
}

/** Picks the plural form for `count` with `Intl.PluralRules`; `{count}` is filled in. */
export function pluralMessage<B extends PluralKey>(base: B, count: number, params?: PluralParams<B>): string {
  const specific = `${base}.${getPluralRules().select(count)}`;
  const template = isMessageKey(specific) ? catalog[specific] : catalog[`${base}.other`];
  return fill(template, { ...params, count: new Intl.NumberFormat(LOCALE).format(count) });
}

/** Formats a date for display with `Intl.DateTimeFormat`. */
export function formatDate(
  date: Date,
  options: Intl.DateTimeFormatOptions = { dateStyle: "medium" },
): string {
  return new Intl.DateTimeFormat(LOCALE, options).format(date);
}
import { message } from "../messages/answer.ts";

export interface QuestionTypeRating {
  readonly _tag: "Rating";
  readonly lowLabel?: string;
  readonly highLabel?: string;
  readonly comment?: boolean;
}

export interface QuestionTypeSingleChoice {
  readonly _tag: "SingleChoice";
  readonly options: ReadonlyArray<string>;
}

export interface QuestionTypeLongText {
  readonly _tag: "LongText";
}

export type QuestionType = QuestionTypeRating | QuestionTypeSingleChoice | QuestionTypeLongText;

export interface QuestionData {
  readonly id: string;
  readonly position: number;
  readonly text: string;
  readonly type: QuestionType;
}

export interface ActionData {
  readonly id: string;
  readonly title: string;
}

export interface RoundContextData {
  readonly roundId: string;
  readonly pulseName: string;
  readonly minimumGroupSize: number;
  readonly questions: ReadonlyArray<QuestionData>;
  readonly actions: ReadonlyArray<ActionData>;
  readonly closeTime: number;
  readonly state: string;
  readonly hasAnswered: boolean;
  readonly aiProcessing: boolean;
}

/**
 * What the lead will and will not see (SPEC 5.2). When the Organization processes comments with AI, the
 * answer page says so right after it (ADR 0015).
 */
export function anonymityStatement(context: RoundContextData): string {
  const anonymity = message("answer.anonymity", { n: context.minimumGroupSize });
  return context.aiProcessing ? `${anonymity} ${message("answer.aiNotice")}` : anonymity;
}

export function parseRoundContext(data: unknown): RoundContextData | null {
  if (typeof data !== "object" || data === null) return null;
  if (!("roundId" in data) || typeof data.roundId !== "string") return null;
  if (!("pulseName" in data) || typeof data.pulseName !== "string") return null;
  if (!("minimumGroupSize" in data) || typeof data.minimumGroupSize !== "number") return null;
  if (!("closeTime" in data) || typeof data.closeTime !== "number") return null;
  if (!("state" in data) || typeof data.state !== "string") return null;
  if (!("hasAnswered" in data) || typeof data.hasAnswered !== "boolean") return null;
  // Absent means off: the flag is new, and a context without it is a context for an Organization without AI processing.
  const aiProcessing = "aiProcessing" in data && data.aiProcessing === true;
  if (!("questions" in data) || !Array.isArray(data.questions)) return null;

  const questions: Array<QuestionData> = [];
  for (const item of data.questions) {
    if (
      typeof item === "object" &&
      item !== null &&
      "id" in item &&
      typeof item.id === "string" &&
      "text" in item &&
      typeof item.text === "string" &&
      "position" in item &&
      typeof item.position === "number"
    ) {
      let qType: QuestionType = { _tag: "Rating", comment: true };
      if ("type" in item && typeof item.type === "object" && item.type !== null && "_tag" in item.type) {
        if (item.type._tag === "Rating") {
          qType = {
            _tag: "Rating",
            lowLabel:
              "lowLabel" in item.type && typeof item.type.lowLabel === "string"
                ? item.type.lowLabel
                : undefined,
            highLabel:
              "highLabel" in item.type && typeof item.type.highLabel === "string"
                ? item.type.highLabel
                : undefined,
            comment:
              "comment" in item.type && typeof item.type.comment === "boolean" ? item.type.comment : true,
          };
        } else if (
          item.type._tag === "SingleChoice" &&
          "options" in item.type &&
          Array.isArray(item.type.options)
        ) {
          const opts: Array<string> = [];
          for (const opt of item.type.options) {
            if (typeof opt === "string") opts.push(opt);
          }
          qType = { _tag: "SingleChoice", options: opts };
        } else if (item.type._tag === "LongText") {
          qType = { _tag: "LongText" };
        }
      }
      questions.push({ id: item.id, position: item.position, text: item.text, type: qType });
    }
  }

  const actions: Array<ActionData> = [];
  if ("actions" in data && Array.isArray(data.actions)) {
    for (const act of data.actions) {
      if (
        typeof act === "object" &&
        act !== null &&
        "id" in act &&
        typeof act.id === "string" &&
        "title" in act &&
        typeof act.title === "string"
      ) {
        actions.push({ id: act.id, title: act.title });
      }
    }
  }

  return {
    roundId: data.roundId,
    pulseName: data.pulseName,
    minimumGroupSize: data.minimumGroupSize,
    questions,
    actions,
    closeTime: data.closeTime,
    state: data.state,
    hasAnswered: data.hasAnswered,
    aiProcessing,
  };
}
import { describe, expect, it } from "vitest";
import { message } from "../messages/answer.ts";
import { anonymityStatement, parseRoundContext } from "./round-context.ts";

const roundContext = (overrides: Record<string, unknown> = {}) => ({
  roundId: "round-1",
  pulseName: "Weekly Pulse",
  minimumGroupSize: 4,
  questions: [{ id: "qv-1", position: 1, text: "How was your week?", type: { _tag: "LongText" } }],
  actions: [],
  closeTime: 1_800_000_000_000,
  state: "open",
  hasAnswered: false,
  ...overrides,
});

const aiNotice =
  "Comments are summarised by an AI service in the EU after names, emails, phone numbers, handles and links are removed. It keeps nothing.";
const anonymity =
  "Your lead only sees combined answers from at least 4 people, never who answered what. Your name is never stored with your answers.";

describe("answer page anonymity statement", () => {
  it("adds the AI notice right after the anonymity statement when AI processing is on", () => {
    const context = parseRoundContext(roundContext({ aiProcessing: true }));
    expect(context).not.toBeNull();
    expect(anonymityStatement(context!)).toBe(`${anonymity} ${aiNotice}`);
    expect(anonymityStatement(context!)).toBe(`${anonymity} ${message("answer.aiNotice")}`);
  });

  it("shows only the anonymity statement when AI processing is off", () => {
    const context = parseRoundContext(roundContext({ aiProcessing: false }));
    expect(context).not.toBeNull();
    expect(anonymityStatement(context!)).toBe(anonymity);
  });

  it("treats a context without the flag as AI processing off", () => {
    const context = parseRoundContext(roundContext());
    expect(context).not.toBeNull();
    expect(context?.aiProcessing).toBe(false);
    expect(anonymityStatement(context!)).toBe(anonymity);
  });

  it("rejects a context that is not an object", () => {
    expect(parseRoundContext("nope")).toBeNull();
  });
});
import { execSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { gzipSync } from "node:zlib";
import { describe, expect, it } from "vitest";

const distDir = resolve(import.meta.dirname, "../../dist");

describe("answer page performance budget", () => {
  it("satisfies HTML, CSS, and JS critical path budgets", () => {
    const htmlPath = resolve(distDir, "answer.html");
    if (!existsSync(htmlPath)) {
      execSync("pnpm --filter @surveybeat/web build", {
        cwd: resolve(import.meta.dirname, "../../../.."),
        stdio: "ignore",
      });
    }
    expect(existsSync(htmlPath), "apps/web/dist/answer.html should exist").toBe(true);

    const html = readFileSync(htmlPath, "utf8");
    const htmlGz = gzipSync(Buffer.from(html), { level: 9 }).length;

    // Budget: HTML ≤ 8 KB (raw and gzip)
    expect(
      html.length,
      `HTML raw size (${(html.length / 1024).toFixed(2)} KB) should be ≤ 8 KB`,
    ).toBeLessThanOrEqual(8 * 1024);
    expect(htmlGz, `HTML gzip size (${(htmlGz / 1024).toFixed(2)} KB) should be ≤ 8 KB`).toBeLessThanOrEqual(
      8 * 1024,
    );

    // Budget: CSS ≤ 2 KB inline (measured as gzip in prototype RESULTS.md, raw also kept minimal)
    const styleMatch = html.match(/<style>([\s\S]*?)<\/style>/);
    expect(styleMatch, "answer.html should have inline <style>").not.toBeNull();
    const inlineCss = styleMatch ? (styleMatch[1] ?? "") : "";
    const inlineCssGz = gzipSync(Buffer.from(inlineCss), { level: 9 }).length;
    expect(
      inlineCssGz,
      `Inline CSS gzip size (${(inlineCssGz / 1024).toFixed(2)} KB) should be ≤ 2 KB`,
    ).toBeLessThanOrEqual(2 * 1024);

    // Budget: JS ≤ 10 KB gzip on critical path
    const scriptSrcMatches = Array.from(html.matchAll(/<script\b[^>]*src="([^"]+)"[^>]*>/g)).map(
      (m) => m[1] ?? "",
    );
    expect(scriptSrcMatches.length).toBeGreaterThan(0);

    // Count each entry script and every chunk it imports statically; dynamic import() is off the critical path.
    const assetsDir = resolve(distDir, "assets");
    const counted = new Set<string>();
    const pending = scriptSrcMatches.map((src) => src.split("/").pop() ?? "");
    let criticalPathJsGz = 0;
    while (pending.length > 0) {
      const fileName = pending.pop() ?? "";
      if (!fileName.endsWith(".js") || counted.has(fileName) || !existsSync(resolve(assetsDir, fileName))) {
        continue;
      }
      counted.add(fileName);
      const fileContent = readFileSync(resolve(assetsDir, fileName));
      criticalPathJsGz += gzipSync(fileContent, { level: 9 }).length;
      const source = fileContent.toString("utf8");
      for (const m of source.matchAll(
        /(?:^|[;\s}])(?:import|export)\s*(?:[^"'()]*?\bfrom\s*)?["']\.\/([^"']+\.js)["']/g,
      )) {
        pending.push(m[1] ?? "");
      }
    }
    expect(counted.size).toBeGreaterThanOrEqual(scriptSrcMatches.length);
    // The app's full catalog must stay off the answer page's critical path.
    expect([...counted].some((name) => name.startsWith("messages-"))).toBe(false);

    expect(
      criticalPathJsGz,
      `Critical path JS (${(criticalPathJsGz / 1024).toFixed(2)} KB gzip in ${[...counted].join(", ")}) should be ≤ 10 KB gzip`,
    ).toBeLessThanOrEqual(10 * 1024);
  });
});

